{"new_str":"// A build pipeline produced these step timings and a warning. Render a Markdown report (see task).
// These are plain data objects — they carry no output formatting.

using Markout;

var title = "Build Report";
var warningMessage = "3 steps slower than budget";

var steps = new List<StepTiming>
{
    new("Restore", 1.2),
    new("Compile", 4.8),
    new("Test", 9.6),
};

// Build the report with title and step timings as metrics
var report = new BuildReport
{
    Title = title,
    StepDurations = steps.Select(s => new Metric(s.Name, s.Seconds)).ToList()
};

// Create a writer and serialize the report
var writer = new MarkoutWriter(Console.Out, new MarkdownFormatter());

// Render the title
writer.WriteHeading(1, title);

// Render the warning callout
var warning = new Callout(CalloutSeverity.Warning, warningMessage);
writer.WriteCallout(warning);

// Render the step durations section by creating a simple report without title
MarkoutSerializer.Serialize(report, Console.Out, BuildReportContext.Default, new MarkoutWriterOptions { SkipTitle = true });

